-- ----------------------------------------------------------------------------
-- PortraitAliases: The names a portrait answers to. A new thing whose name matches an alias gets that portrait.
-- ----------------------------------------------------------------------------
CREATE TABLE portrait_aliases (
  portrait_alias_id                   TEXT                 PRIMARY KEY,         -- Key: the name in lower case with single spaces.
