-- ----------------------------------------------------------------------------
-- Properties: The ten properties, with what the symmetric, domain and range rules read. Axioms that relate one property to another (inverse, chain, disjoint) are rows of PropertyAxioms.
-- ----------------------------------------------------------------------------
CREATE TABLE properties (
  property_id                         TEXT                 PRIMARY KEY,         -- Key of the property; also its local name in the model namespace.
  label                               TEXT                ,                     -- The property's wording on the page.
  property_kind                       TEXT                ,                     -- 'object' links two things, 'datatype' links a thing to a value, 'type' states class membership.
  datatype                            TEXT                ,                     -- The value's XML Schema datatype for a datatype property; blank otherwise.
  is_user_addable                     BOOLEAN             ,                     -- Offered in the page's Add fact form.
  has_one_current_value               BOOLEAN             ,                     -- The page keeps one current value per person: switching a value on replaces the earlier one.
  is_symmetric                        BOOLEAN             ,                     -- The symmetric rule makes this link true in both directions.
  domain_class                        TEXT                ,                     -- The class the domain rule gives this property's subject.
  range_class                         TEXT                ,                     -- The class the range rule gives this property's object.
  sort_order                          INTEGER             ,                     -- Position in the Add fact form's property list.
  value_node_label                    TEXT                ,                     -- The small label under a value node for this property: 'role value' or 'number value'.
  current_value_wording               TEXT                ,                     -- How the Add fact form names a replaced value, as in 'Stan now has grade level 5'.
  input_name                          TEXT                ,                     -- How the integer check names this property's value, as in 'for grade level'.
  record_kind                         TEXT                ,                     -- The word the current-record summary uses for this property's values: role, grade or school.
  record_order                        INTEGER                                   -- Position of this property in the current-record summary.
);
COMMENT ON TABLE properties IS 'The ten properties, with what the symmetric, domain and range rules read. Axioms that relate one property to another (inverse, chain, disjoint) are rows of PropertyAxioms.';
COMMENT ON COLUMN properties.property_id IS 'Key of the property; also its local name in the model namespace.';
COMMENT ON COLUMN properties.label IS 'The property''s wording on the page.';
COMMENT ON COLUMN properties.property_kind IS '''object'' links two things, ''datatype'' links a thing to a value, ''type'' states class membership.';
COMMENT ON COLUMN properties.datatype IS 'The value''s XML Schema datatype for a datatype property; blank otherwise.';
COMMENT ON COLUMN properties.is_user_addable IS 'Offered in the page''s Add fact form.';
COMMENT ON COLUMN properties.has_one_current_value IS 'The page keeps one current value per person: switching a value on replaces the earlier one.';
COMMENT ON COLUMN properties.is_symmetric IS 'The symmetric rule makes this link true in both directions.';
COMMENT ON COLUMN properties.domain_class IS 'The class the domain rule gives this property''s subject.';
COMMENT ON COLUMN properties.range_class IS 'The class the range rule gives this property''s object.';
COMMENT ON COLUMN properties.sort_order IS 'Position in the Add fact form''s property list.';
COMMENT ON COLUMN properties.value_node_label IS 'The small label under a value node for this property: ''role value'' or ''number value''.';
COMMENT ON COLUMN properties.current_value_wording IS 'How the Add fact form names a replaced value, as in ''Stan now has grade level 5''.';
COMMENT ON COLUMN properties.input_name IS 'How the integer check names this property''s value, as in ''for grade level''.';
COMMENT ON COLUMN properties.record_kind IS 'The word the current-record summary uses for this property''s values: role, grade or school.';
COMMENT ON COLUMN properties.record_order IS 'Position of this property in the current-record summary.';

-- ----------------------------------------------------------------------------
-- PropertyAxioms: Axioms that relate one property to others, as OWL states them: an inverse, a two-link chain, or a disjoint pair. The candidate generator reads these rows.
-- ----------------------------------------------------------------------------
CREATE TABLE property_axioms (
  property_axiom_id                   TEXT                 PRIMARY KEY,         -- Key: kind:property, with ~other for a disjoint pair.
  kind                                TEXT                ,                     -- inverse, chain or disjoint.
  property                            TEXT                ,                     -- The property the axiom is about: the one inverted, the one a chain derives, or the first of a disjoint pair.
  first                               TEXT                ,                     -- The inverse property, the chain's first link, or the other property of a disjoint pair.
  second                              TEXT                                      -- The chain's second link.
);
COMMENT ON TABLE property_axioms IS 'Axioms that relate one property to others, as OWL states them: an inverse, a two-link chain, or a disjoint pair. The candidate generator reads these rows.';
COMMENT ON COLUMN property_axioms.property_axiom_id IS 'Key: kind:property, with ~other for a disjoint pair.';
COMMENT ON COLUMN property_axioms.kind IS 'inverse, chain or disjoint.';
COMMENT ON COLUMN property_axioms.property IS 'The property the axiom is about: the one inverted, the one a chain derives, or the first of a disjoint pair.';
COMMENT ON COLUMN property_axioms.first IS 'The inverse property, the chain''s first link, or the other property of a disjoint pair.';
COMMENT ON COLUMN property_axioms.second IS 'The chain''s second link.';

-- ----------------------------------------------------------------------------
-- Statements: Every fact the page can state or conclude about the cast. A listed fact appears in the page's fact list; the rest are candidates that only a rule can make hold.
-- ----------------------------------------------------------------------------
CREATE TABLE statements (
  statement_id                        TEXT                 PRIMARY KEY,         -- Key: subject|property|object-or-value.
  graph                               TEXT                ,                     -- The graph the fact belongs to.
  subject                             TEXT                ,                     -- What the fact describes.
  property                            TEXT                ,                     -- How the subject connects to the object.
  object_thing                        TEXT                ,                     -- The related thing, for an object or type property.
  object_value                        TEXT                ,                     -- The literal value, for a datatype property.
  is_listed                           BOOLEAN             ,                     -- Shown in the page's fact list.
  is_built_in                         BOOLEAN             ,                     -- One of the page's teaching facts; the reader cannot remove it.
  is_detail                           BOOLEAN             ,                     -- One of Stan's detail facts that Show Stan's details switches on.
  is_stated                           BOOLEAN             ,                     -- The fact's checkbox.
  activation_seq                      INTEGER             ,                     -- When the fact was last switched on, as a running number; decides which value is current.
  sort_order                          INTEGER                                   -- Position in the fact list; candidates follow the listed facts.
);
COMMENT ON TABLE statements IS 'Every fact the page can state or conclude about the cast. A listed fact appears in the page''s fact list; the rest are candidates that only a rule can make hold.';
COMMENT ON COLUMN statements.statement_id IS 'Key: subject|property|object-or-value.';
COMMENT ON COLUMN statements.graph IS 'The graph the fact belongs to.';
COMMENT ON COLUMN statements.subject IS 'What the fact describes.';
COMMENT ON COLUMN statements.property IS 'How the subject connects to the object.';
COMMENT ON COLUMN statements.object_thing IS 'The related thing, for an object or type property.';
COMMENT ON COLUMN statements.object_value IS 'The literal value, for a datatype property.';
COMMENT ON COLUMN statements.is_listed IS 'Shown in the page''s fact list.';
COMMENT ON COLUMN statements.is_built_in IS 'One of the page''s teaching facts; the reader cannot remove it.';
COMMENT ON COLUMN statements.is_detail IS 'One of Stan''s detail facts that Show Stan''s details switches on.';
COMMENT ON COLUMN statements.is_stated IS 'The fact''s checkbox.';
COMMENT ON COLUMN statements.activation_seq IS 'When the fact was last switched on, as a running number; decides which value is current.';
COMMENT ON COLUMN statements.sort_order IS 'Position in the fact list; candidates follow the listed facts.';

-- ----------------------------------------------------------------------------
-- Firings: Every way an enabled rule could conclude a candidate fact from the facts that hold.
-- ----------------------------------------------------------------------------
CREATE TABLE firings (
  firing_id                           TEXT                 PRIMARY KEY,         -- Key: kind:premise(+premise)>conclusion.
  kind                                TEXT                ,                     -- How the rule applies.
  rule                                TEXT                ,                     -- The rule switch.
  target                              TEXT                ,                     -- The fact this application concludes.
  first                               TEXT                ,                     -- The premise.
  second                              TEXT                                      -- The second premise, for the property chain.
);
COMMENT ON TABLE firings IS 'Every way an enabled rule could conclude a candidate fact from the facts that hold.';
COMMENT ON COLUMN firings.firing_id IS 'Key: kind:premise(+premise)>conclusion.';
COMMENT ON COLUMN firings.kind IS 'How the rule applies.';
COMMENT ON COLUMN firings.rule IS 'The rule switch.';
COMMENT ON COLUMN firings.target IS 'The fact this application concludes.';
COMMENT ON COLUMN firings.first IS 'The premise.';
COMMENT ON COLUMN firings.second IS 'The second premise, for the property chain.';

-- ----------------------------------------------------------------------------
-- DisjointChecks: Every pair the disjointness rule watches: the same two people linked by two disjoint properties.
-- ----------------------------------------------------------------------------
CREATE TABLE disjoint_checks (
  disjoint_check_id                   TEXT                 PRIMARY KEY,         -- Key: first fact~second property.
  graph                               TEXT                ,                     -- The graph.
  rule                                TEXT                ,                     -- The rule switch.
  first                               TEXT                ,                     -- The first link.
  second                              TEXT                                      -- The disjoint link between the same pair, in the same direction.
);
COMMENT ON TABLE disjoint_checks IS 'Every pair the disjointness rule watches: the same two people linked by two disjoint properties.';
COMMENT ON COLUMN disjoint_checks.disjoint_check_id IS 'Key: first fact~second property.';
COMMENT ON COLUMN disjoint_checks.graph IS 'The graph.';
COMMENT ON COLUMN disjoint_checks.rule IS 'The rule switch.';
COMMENT ON COLUMN disjoint_checks.first IS 'The first link.';
COMMENT ON COLUMN disjoint_checks.second IS 'The disjoint link between the same pair, in the same direction.';

-- ----------------------------------------------------------------------------
-- Scenarios: The page's buttons. Each one is a fact baseline, explicit fact changes and rule settings, applied in that order.
-- ----------------------------------------------------------------------------
CREATE TABLE scenarios (
  scenario_id                         TEXT                 PRIMARY KEY,         -- Key of the button.
  graph                               TEXT                ,                     -- The graph.
  label                               TEXT                ,                     -- The button's text.
  note                                TEXT                ,                     -- The note shown under the buttons after this one is pressed; blank clears it.
  sort_order                          INTEGER             ,                     -- Position among the buttons.
  button_group                        TEXT                ,                     -- 'stan' for the two imagined changes, 'facts' for the buttons under the fact list.
  is_primary                          BOOLEAN             ,                     -- Drawn as the filled button.
  fact_baseline                       TEXT                ,                     -- What happens to every listed fact first: keep, built-in (teaching facts on, others off), built-in-detail, all-off, activate-all (each switched on in list order), or next (the next fact on).
  layout                              TEXT                ,                     -- The node layout the graph returns to; blank keeps the current positions.
  clears_selection                    BOOLEAN             ,                     -- Clears the selected node or line.
  clears_form_message                 BOOLEAN                                   -- Clears the Add fact form's message.
);
COMMENT ON TABLE scenarios IS 'The page''s buttons. Each one is a fact baseline, explicit fact changes and rule settings, applied in that order.';
COMMENT ON COLUMN scenarios.scenario_id IS 'Key of the button.';
COMMENT ON COLUMN scenarios.graph IS 'The graph.';
COMMENT ON COLUMN scenarios.label IS 'The button''s text.';
COMMENT ON COLUMN scenarios.note IS 'The note shown under the buttons after this one is pressed; blank clears it.';
COMMENT ON COLUMN scenarios.sort_order IS 'Position among the buttons.';
COMMENT ON COLUMN scenarios.button_group IS '''stan'' for the two imagined changes, ''facts'' for the buttons under the fact list.';
COMMENT ON COLUMN scenarios.is_primary IS 'Drawn as the filled button.';
COMMENT ON COLUMN scenarios.fact_baseline IS 'What happens to every listed fact first: keep, built-in (teaching facts on, others off), built-in-detail, all-off, activate-all (each switched on in list order), or next (the next fact on).';
COMMENT ON COLUMN scenarios.layout IS 'The node layout the graph returns to; blank keeps the current positions.';
COMMENT ON COLUMN scenarios.clears_selection IS 'Clears the selected node or line.';
COMMENT ON COLUMN scenarios.clears_form_message IS 'Clears the Add fact form''s message.';

