CREATE TABLE rulebook_tools (
  rulebook_tool_id                    TEXT                 PRIMARY KEY,         -- Key of the tool.
  label                               TEXT                ,                     -- The tool's name.
  adds                                TEXT                ,                     -- What it adds, for this form of the rulebook.
  href                                TEXT                ,                     -- Where its link goes; 'editor' means this form's running rulebook editor.
  link_text                           TEXT                ,                     -- The link's text.
  sort_order                          INTEGER             ,                     -- Position in the panel.
  form                                TEXT                                      -- Which form of the rulebook the tool is about: ontology (things, properties, statements) or concept (tables).
);
COMMENT ON TABLE rulebook_tools IS 'What each rulebook tool adds, for each form of the rulebook. The explainer page and the ontology form''s editor list the ontology form''s tools; the concept form''s editor lists the concept form''s. The two forms are the same facts, so they list the same tools.';
