CREATE OR REPLACE FUNCTION calc_statements_object_text(p_statement_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN (((SELECT NULLIF(object_thing, '') FROM statements WHERE statement_id = p_statement_id)) IS NULL OR ((SELECT NULLIF(object_thing, '') FROM statements WHERE statement_id = p_statement_id))::text = '') THEN ((SELECT NULLIF(object_value, '') FROM statements WHERE statement_id = p_statement_id))::text ELSE (calc_statements_object_label(p_statement_id))::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_statements_name
-- Field: Statements.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_statements_name(p_statement_id TEXT)
RETURNS TEXT AS $$
  SELECT (CONCAT(calc_statements_subject_label(p_statement_id), ' ', calc_statements_property_label(p_statement_id), ' ', calc_statements_object_text(p_statement_id)))::text;
$$ LANGUAGE sql STABLE;

-- calc_statements_words
-- Field: Statements.Words
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_statements_words(p_statement_id TEXT)
RETURNS TEXT AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_statements_literal_quote(p_statement_id) AS val) SELECT (CONCAT(calc_statements_subject_label(p_statement_id), ' ', calc_statements_property_label(p_statement_id), ' ', CASE WHEN (((SELECT NULLIF(object_thing, '') FROM statements WHERE statement_id = p_statement_id)) IS NULL OR ((SELECT NULLIF(object_thing, '') FROM statements WHERE statement_id = p_statement_id))::text = '') THEN (CONCAT((SELECT val FROM __erb_dedup_v1), (SELECT NULLIF(object_value, '') FROM statements WHERE statement_id = p_statement_id), (SELECT val FROM __erb_dedup_v1), calc_statements_literal_type_marker(p_statement_id), calc_statements_property_datatype(p_statement_id)))::text ELSE (calc_statements_object_label(p_statement_id))::text END))::text;
$$ LANGUAGE sql STABLE;

-- calc_statements_source
-- Field: Statements.Source
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_statements_source(p_statement_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN COALESCE((SELECT is_built_in FROM statements WHERE statement_id = p_statement_id), FALSE) THEN (calc_statements_built_in_source_text(p_statement_id))::text ELSE (calc_statements_user_source_text(p_statement_id))::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_statements_subject_property_key
-- Field: Statements.SubjectPropertyKey
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_statements_subject_property_key(p_statement_id TEXT)
RETURNS TEXT AS $$
  SELECT (CONCAT((SELECT NULLIF(subject, '') FROM statements WHERE statement_id = p_statement_id), '|', (SELECT NULLIF(property, '') FROM statements WHERE statement_id = p_statement_id)))::text;
$$ LANGUAGE sql STABLE;

-- calc_statements_latest_sibling_activation_seq
-- Field: Statements.LatestSiblingActivationSeq
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_statements_latest_sibling_activation_seq(p_statement_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COALESCE(MAX((activation_seq)::numeric), 0) FROM statements erb_r1 WHERE ((SELECT (CONCAT(NULLIF(erb_r1.subject, ''), '|', NULLIF(erb_r1.property, '')))::text))::text = (SELECT calc_statements_subject_property_key(p_statement_id))))::integer;
$$ LANGUAGE sql STABLE;

-- calc_statements_is_in_effect
-- Field: Statements.IsInEffect
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_statements_is_in_effect(p_statement_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((SELECT is_stated FROM statements WHERE statement_id = p_statement_id), FALSE), FALSE) AND COALESCE((COALESCE(NOT (COALESCE(calc_statements_property_has_one_current_value(p_statement_id), FALSE)), FALSE) OR COALESCE(COALESCE((SELECT activation_seq FROM statements WHERE statement_id = p_statement_id), 0) = COALESCE(calc_statements_latest_sibling_activation_seq(p_statement_id), 0), FALSE)), FALSE)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_statements_listed_unit
-- Field: Statements.ListedUnit
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_statements_listed_unit(p_statement_id TEXT)
RETURNS INTEGER AS $$
  SELECT (CASE WHEN COALESCE((SELECT is_listed FROM statements WHERE statement_id = p_statement_id), FALSE) THEN (1)::text ELSE (0)::text END)::integer;
$$ LANGUAGE sql STABLE;

-- calc_statements_in_effect_unit
-- Field: Statements.InEffectUnit
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_statements_in_effect_unit(p_statement_id TEXT)
RETURNS INTEGER AS $$
  SELECT (CASE WHEN calc_statements_is_in_effect(p_statement_id) THEN (1)::text ELSE (0)::text END)::integer;
$$ LANGUAGE sql STABLE;

-- calc_statements_listed_off_unit
-- Field: Statements.ListedOffUnit
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_statements_listed_off_unit(p_statement_id TEXT)
RETURNS INTEGER AS $$
  SELECT (CASE WHEN (COALESCE(COALESCE((SELECT is_listed FROM statements WHERE statement_id = p_statement_id), FALSE), FALSE) AND COALESCE(NOT (COALESCE(calc_statements_is_in_effect(p_statement_id), FALSE)), FALSE)) THEN (1)::text ELSE (0)::text END)::integer;
$$ LANGUAGE sql STABLE;

-- calc_statements_is_next_to_add
-- Field: Statements.IsNextToAdd
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_statements_is_next_to_add(p_statement_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((calc_statements_listed_off_unit(p_statement_id))::NUMERIC, 0) = 1, FALSE) AND COALESCE(COALESCE((SELECT sort_order FROM statements WHERE statement_id = p_statement_id), 0) = COALESCE(calc_statements_next_fact_sort_order(p_statement_id), 0), FALSE)));
$$ LANGUAGE sql STABLE;

-- calc_statements_count_of_inverse_firings
-- Field: Statements.CountOfInverseFirings
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_statements_count_of_inverse_firings(p_statement_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COALESCE(SUM((((SELECT (CASE WHEN (COALESCE(calc_firings_rule_enabled(erb_r1.firing_id), FALSE) AND COALESCE(COALESCE(NULLIF(erb_r1.kind, ''), '') = 'inverse', FALSE) AND COALESCE(calc_firings_first_is_in_effect(erb_r1.firing_id), FALSE)) THEN (1)::text ELSE (0)::text END)::integer))::integer)::numeric), 0) FROM firings erb_r1 WHERE target = p_statement_id))::integer;
$$ LANGUAGE sql STABLE;

-- calc_statements_count_of_symmetric_firings
-- Field: Statements.CountOfSymmetricFirings
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_statements_count_of_symmetric_firings(p_statement_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COALESCE(SUM((((SELECT (CASE WHEN (COALESCE(calc_firings_rule_enabled(erb_r1.firing_id), FALSE) AND COALESCE(COALESCE(NULLIF(erb_r1.kind, ''), '') = 'symmetric', FALSE) AND COALESCE(calc_firings_first_is_in_effect(erb_r1.firing_id), FALSE)) THEN (1)::text ELSE (0)::text END)::integer))::integer)::numeric), 0) FROM firings erb_r1 WHERE target = p_statement_id))::integer;
$$ LANGUAGE sql STABLE;

-- calc_statements_holds_before_chain
-- Field: Statements.HoldsBeforeChain
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_statements_holds_before_chain(p_statement_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (CASE WHEN (COALESCE(calc_statements_is_in_effect(p_statement_id), FALSE) OR COALESCE(COALESCE((calc_statements_count_of_inverse_firings(p_statement_id))::NUMERIC, 0) > 0, FALSE) OR COALESCE(COALESCE((calc_statements_count_of_symmetric_firings(p_statement_id))::NUMERIC, 0) > 0, FALSE)) THEN TRUE ELSE NULL END)::boolean;
$$ LANGUAGE sql STABLE;

-- calc_statements_count_of_chain_firings
-- Field: Statements.CountOfChainFirings
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_statements_count_of_chain_firings(p_statement_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COALESCE(SUM((((SELECT (CASE WHEN (COALESCE(calc_firings_rule_enabled(erb_r1.firing_id), FALSE) AND COALESCE(COALESCE(NULLIF(erb_r1.kind, ''), '') = 'chain', FALSE) AND COALESCE(calc_firings_first_holds_before_chain(erb_r1.firing_id), FALSE) AND COALESCE(calc_firings_second_holds_before_chain(erb_r1.firing_id), FALSE)) THEN (1)::text ELSE (0)::text END)::integer))::integer)::numeric), 0) FROM firings erb_r1 WHERE target = p_statement_id))::integer;
$$ LANGUAGE sql STABLE;

-- calc_statements_holds_before_typing
-- Field: Statements.HoldsBeforeTyping
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_statements_holds_before_typing(p_statement_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (CASE WHEN (COALESCE(calc_statements_holds_before_chain(p_statement_id), FALSE) OR COALESCE(COALESCE((calc_statements_count_of_chain_firings(p_statement_id))::NUMERIC, 0) > 0, FALSE)) THEN TRUE ELSE NULL END)::boolean;
$$ LANGUAGE sql STABLE;

-- calc_statements_count_of_type_firings
-- Field: Statements.CountOfTypeFirings
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_statements_count_of_type_firings(p_statement_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COALESCE(SUM((((SELECT (CASE WHEN (COALESCE(calc_firings_rule_enabled(erb_r1.firing_id), FALSE) AND COALESCE((COALESCE(COALESCE(NULLIF(erb_r1.kind, ''), '') = 'domain', FALSE) OR COALESCE(COALESCE(NULLIF(erb_r1.kind, ''), '') = 'range', FALSE)), FALSE) AND COALESCE(calc_firings_first_holds_before_typing(erb_r1.firing_id), FALSE)) THEN (1)::text ELSE (0)::text END)::integer))::integer)::numeric), 0) FROM firings erb_r1 WHERE target = p_statement_id))::integer;
$$ LANGUAGE sql STABLE;

-- calc_statements_holds
-- Field: Statements.Holds
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_statements_holds(p_statement_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (CASE WHEN (COALESCE(calc_statements_holds_before_typing(p_statement_id), FALSE) OR COALESCE(COALESCE((calc_statements_count_of_type_firings(p_statement_id))::NUMERIC, 0) > 0, FALSE)) THEN TRUE ELSE NULL END)::boolean;
$$ LANGUAGE sql STABLE;

-- calc_statements_is_conclusion
-- Field: Statements.IsConclusion
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_statements_is_conclusion(p_statement_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (CASE WHEN (COALESCE(calc_statements_holds(p_statement_id), FALSE) AND COALESCE(NOT (COALESCE(calc_statements_is_in_effect(p_statement_id), FALSE)), FALSE)) THEN TRUE ELSE NULL END)::boolean;
$$ LANGUAGE sql STABLE;

-- calc_statements_holds_unit
-- Field: Statements.HoldsUnit
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_statements_holds_unit(p_statement_id TEXT)
RETURNS INTEGER AS $$
  SELECT (CASE WHEN calc_statements_holds(p_statement_id) THEN (1)::text ELSE (0)::text END)::integer;
$$ LANGUAGE sql STABLE;

-- calc_statements_conclusion_unit
-- Field: Statements.ConclusionUnit
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_statements_conclusion_unit(p_statement_id TEXT)
RETURNS INTEGER AS $$
  SELECT (CASE WHEN calc_statements_is_conclusion(p_statement_id) THEN (1)::text ELSE (0)::text END)::integer;
$$ LANGUAGE sql STABLE;

-- calc_statements_parent_unit
-- Field: Statements.ParentUnit
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_statements_parent_unit(p_statement_id TEXT)
RETURNS INTEGER AS $$
  SELECT (CASE WHEN (COALESCE(calc_statements_holds(p_statement_id), FALSE) AND COALESCE(COALESCE((SELECT NULLIF(property, '') FROM statements WHERE statement_id = p_statement_id), '') = 'isParentOf', FALSE)) THEN (1)::text ELSE (0)::text END)::integer;
$$ LANGUAGE sql STABLE;

-- calc_statements_grandparent_unit
-- Field: Statements.GrandparentUnit
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_statements_grandparent_unit(p_statement_id TEXT)
RETURNS INTEGER AS $$
  SELECT (CASE WHEN (COALESCE(calc_statements_holds(p_statement_id), FALSE) AND COALESCE(COALESCE((SELECT NULLIF(property, '') FROM statements WHERE statement_id = p_statement_id), '') = 'isGrandparentOf', FALSE)) THEN (1)::text ELSE (0)::text END)::integer;
$$ LANGUAGE sql STABLE;

-- calc_statements_place_unit
-- Field: Statements.PlaceUnit
-- Type: calculated | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_statements_place_unit(p_statement_id TEXT)
RETURNS INTEGER AS $$
  SELECT (CASE WHEN (COALESCE(calc_statements_holds(p_statement_id), FALSE) AND COALESCE(COALESCE((SELECT NULLIF(property, '') FROM statements WHERE statement_id = p_statement_id), '') = 'attends', FALSE)) THEN (1)::text ELSE (0)::text END)::integer;
$$ LANGUAGE sql STABLE;

-- calc_statements_first_pre_chain_order_key
-- Field: Statements.FirstPreChainOrderKey
-- Type: aggregation | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_statements_first_pre_chain_order_key(p_statement_id TEXT)
RETURNS NUMERIC AS $$
  SELECT ((SELECT COALESCE(MIN((((SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_firings_first_sort_order(erb_r1.firing_id)) AS v OFFSET 0) __safe_numeric), 0) * COALESCE(10, 0))) AS v OFFSET 0) __safe_numeric), 0) + COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_firings_kind_sort_order(erb_r1.firing_id)) AS v OFFSET 0) __safe_numeric), 0)))::numeric))::numeric)::numeric), 0) FROM firings erb_r1 WHERE target = p_statement_id AND ((SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_firings_inverse_fired_unit(erb_r1.firing_id)) AS v OFFSET 0) __safe_numeric), 0) + COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_firings_symmetric_fired_unit(erb_r1.firing_id)) AS v OFFSET 0) __safe_numeric), 0)))::integer))::integer = 1))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_statements_snap_position
-- Field: Statements.SnapPosition
-- Type: calculated | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_statements_snap_position(p_statement_id TEXT)
RETURNS NUMERIC AS $$
  SELECT (CASE WHEN calc_statements_is_in_effect(p_statement_id) THEN ((SELECT sort_order FROM statements WHERE statement_id = p_statement_id))::text ELSE (CASE WHEN calc_statements_holds_before_chain(p_statement_id) THEN ((COALESCE(100000, 0) + COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_statements_first_pre_chain_order_key(p_statement_id)) AS v OFFSET 0) __safe_numeric), 0)))::text ELSE (0)::text END)::text END)::numeric;
$$ LANGUAGE sql STABLE;

-- calc_statements_first_fired_order_key
-- Field: Statements.FirstFiredOrderKey
-- Type: aggregation | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_statements_first_fired_order_key(p_statement_id TEXT)
RETURNS NUMERIC AS $$
  SELECT ((SELECT COALESCE(MIN((((SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_firings_round(erb_r1.firing_id)) AS v OFFSET 0) __safe_numeric), 0) * COALESCE(1000000000000000, 0))) AS v OFFSET 0) __safe_numeric), 0) + COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_firings_first_snap_position(erb_r1.firing_id)) AS v OFFSET 0) __safe_numeric), 0) * COALESCE(100000000, 0))) AS v OFFSET 0) __safe_numeric), 0) + COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_firings_kind_sort_order(erb_r1.firing_id)) AS v OFFSET 0) __safe_numeric), 0) * COALESCE(10000000, 0))) AS v OFFSET 0) __safe_numeric), 0) + COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (CASE WHEN ((NULLIF(erb_r1.second, '')) IS NULL OR (NULLIF(erb_r1.second, ''))::text = '') THEN (0)::text ELSE (calc_firings_second_snap_position(erb_r1.firing_id))::text END) AS v OFFSET 0) __safe_numeric), 0))) AS v OFFSET 0) __safe_numeric), 0))) AS v OFFSET 0) __safe_numeric), 0)))::numeric))::numeric)::numeric), 0) FROM firings erb_r1 WHERE target = p_statement_id AND ((SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_firings_inverse_fired_unit(erb_r1.firing_id)) AS v OFFSET 0) __safe_numeric), 0) + COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_firings_symmetric_fired_unit(erb_r1.firing_id)) AS v OFFSET 0) __safe_numeric), 0) + COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_firings_chain_fired_unit(erb_r1.firing_id)) AS v OFFSET 0) __safe_numeric), 0) + COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_firings_type_fired_unit(erb_r1.firing_id)) AS v OFFSET 0) __safe_numeric), 0))) AS v OFFSET 0) __safe_numeric), 0))) AS v OFFSET 0) __safe_numeric), 0)))::integer))::integer = 1))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_statements_count_of_chosen_firings
-- Field: Statements.CountOfChosenFirings
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_statements_count_of_chosen_firings(p_statement_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COALESCE(SUM((((SELECT (CASE WHEN calc_firings_is_chosen(erb_r1.firing_id) THEN (1)::text ELSE (0)::text END)::integer))::integer)::numeric), 0) FROM firings erb_r1 WHERE target = p_statement_id))::integer;
$$ LANGUAGE sql STABLE;

-- calc_statements_subject_node_key
-- Field: Statements.SubjectNodeKey
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_statements_subject_node_key(p_statement_id TEXT)
RETURNS TEXT AS $$
  SELECT ((SELECT NULLIF(subject, '') FROM statements WHERE statement_id = p_statement_id))::text;
$$ LANGUAGE sql STABLE;

-- calc_statements_object_node_key
-- Field: Statements.ObjectNodeKey
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_statements_object_node_key(p_statement_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN (((SELECT NULLIF(object_thing, '') FROM statements WHERE statement_id = p_statement_id)) IS NULL OR ((SELECT NULLIF(object_thing, '') FROM statements WHERE statement_id = p_statement_id))::text = '') THEN (CONCAT('literal|', (SELECT NULLIF(object_value, '') FROM statements WHERE statement_id = p_statement_id), '|', calc_statements_property_datatype(p_statement_id)))::text ELSE ((SELECT NULLIF(object_thing, '') FROM statements WHERE statement_id = p_statement_id))::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_statements_object_node_kind
-- Field: Statements.ObjectNodeKind
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_statements_object_node_kind(p_statement_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN (((SELECT NULLIF(object_thing, '') FROM statements WHERE statement_id = p_statement_id)) IS NULL OR ((SELECT NULLIF(object_thing, '') FROM statements WHERE statement_id = p_statement_id))::text = '') THEN ('value')::text ELSE (calc_statements_object_thing_node_kind(p_statement_id))::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_statements_count_of_violations_as_first
-- Field: Statements.CountOfViolationsAsFirst
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_statements_count_of_violations_as_first(p_statement_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COALESCE(SUM((((SELECT (CASE WHEN (COALESCE(calc_disjoint_checks_rule_enabled(erb_r1.disjoint_check_id), FALSE) AND COALESCE(calc_disjoint_checks_first_holds(erb_r1.disjoint_check_id), FALSE) AND COALESCE(calc_disjoint_checks_second_holds(erb_r1.disjoint_check_id), FALSE)) THEN (1)::text ELSE (0)::text END)::integer))::integer)::numeric), 0) FROM disjoint_checks erb_r1 WHERE first = p_statement_id))::integer;
$$ LANGUAGE sql STABLE;

-- calc_statements_count_of_violations_as_second
-- Field: Statements.CountOfViolationsAsSecond
-- Type: aggregation | DataType: integer | Returns: INTEGER


CREATE OR REPLACE FUNCTION calc_statements_count_of_violations_as_second(p_statement_id TEXT)
RETURNS INTEGER AS $$
  SELECT ((SELECT COALESCE(SUM((((SELECT (CASE WHEN (COALESCE(calc_disjoint_checks_rule_enabled(erb_r1.disjoint_check_id), FALSE) AND COALESCE(calc_disjoint_checks_first_holds(erb_r1.disjoint_check_id), FALSE) AND COALESCE(calc_disjoint_checks_second_holds(erb_r1.disjoint_check_id), FALSE)) THEN (1)::text ELSE (0)::text END)::integer))::integer)::numeric), 0) FROM disjoint_checks erb_r1 WHERE second = p_statement_id))::integer;
$$ LANGUAGE sql STABLE;

-- calc_statements_is_in_contradiction
-- Field: Statements.IsInContradiction
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_statements_is_in_contradiction(p_statement_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE(COALESCE((calc_statements_count_of_violations_as_first(p_statement_id))::NUMERIC, 0) > 0, FALSE) OR COALESCE(COALESCE((calc_statements_count_of_violations_as_second(p_statement_id))::NUMERIC, 0) > 0, FALSE)));
$$ LANGUAGE sql STABLE;

-- calc_firings_rule_enabled
-- Field: Firings.RuleEnabled
-- Type: lookup | DataType: boolean | Returns: BOOLEAN
-- Lookup: IsEnabled from related Rules


CREATE OR REPLACE FUNCTION calc_firings_rule_enabled(p_firing_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (SELECT is_enabled::boolean FROM rules WHERE rule_id = (SELECT rule FROM firings WHERE firing_id = p_firing_id));
$$ LANGUAGE sql STABLE;

-- calc_firings_kind_wording
-- Field: Firings.KindWording
-- Type: lookup | DataType: string | Returns: TEXT
-- Lookup: Wording from related FiringKinds


CREATE OR REPLACE FUNCTION calc_firings_kind_wording(p_firing_id TEXT)
RETURNS TEXT AS $$
  SELECT (SELECT wording::text FROM firing_kinds WHERE firing_kind_id = (SELECT kind FROM firings WHERE firing_id = p_firing_id));
$$ LANGUAGE sql STABLE;

-- calc_firings_kind_sort_order
-- Field: Firings.KindSortOrder
-- Type: lookup | DataType: integer | Returns: INTEGER
-- Lookup: SortOrder from related FiringKinds


