-- ----------------------------------------------------------------------------
-- vw_graphs: The explainer page as one graph: its wording variables and its totals.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_graphs CASCADE;
CREATE VIEW vw_graphs WITH (security_invoker = ON) AS
SELECT
  t.graph_id,                                                                   -- Key of the graph.
  t.label,                                                                      -- Display name of the graph.
  t.literal_quote,                                                              -- The quote mark written around a literal value in a fact's wording.
  t.literal_type_marker,                                                        -- The marker written between a literal value and its datatype, as in Turtle.
  t.built_in_source_text,                                                       -- Source line shown for a fact the page states as a teaching example.
  t.user_source_text,                                                           -- Source line shown for a fact the reader stated.
  t.no_conclusions_text,                                                        -- Message shown when the selected facts and rules add no conclusion.
  calc_graphs_name(t.graph_id) AS name,                                         -- Order 1. Display name of the graph.
  calc_graphs_count_of_stated_facts(t.graph_id) AS count_of_stated_facts,       -- Order 5. Facts that are switched on and in effect.
  calc_graphs_count_of_conclusions(t.graph_id) AS count_of_conclusions,         -- Order 18. Facts that hold only because an enabled rule concluded them.
  calc_graphs_count_of_violations(t.graph_id) AS count_of_violations,           -- Order 18. Disjointness checks that found both links between the same pair.
  calc_graphs_is_consistent(t.graph_id) AS is_consistent,                       -- Order 19. True when no enabled disjointness rule is violated.
  calc_graphs_conclusions_message(t.graph_id) AS conclusions_message,           -- Order 19. The empty-state message for the conclusions panel, blank when there are conclusions.
  calc_graphs_count_of_facts_to_add(t.graph_id) AS count_of_facts_to_add,       -- Order 5. Listed facts that are not in effect; the Add next fact button is enabled while this is above zero.
  calc_graphs_has_facts_to_add(t.graph_id) AS has_facts_to_add,                 -- Order 6. True while some listed fact can still be added.
  calc_graphs_next_fact_sort_order(t.graph_id) AS next_fact_sort_order,         -- Order 5. List position of the first listed fact that is not in effect.
  calc_graphs_max_activation_seq(t.graph_id) AS max_activation_seq,             -- Order 1. Highest activation number used so far.
  calc_graphs_next_activation_seq(t.graph_id) AS next_activation_seq,           -- Order 2. The activation number the next switched-on fact takes.
  calc_graphs_max_listed_sort_order(t.graph_id) AS max_listed_sort_order,       -- Order 2. Highest list position among listed facts.
  calc_graphs_next_listed_sort_order(t.graph_id) AS next_listed_sort_order,     -- Order 3. The list position a newly added fact takes.
  calc_graphs_max_sort_order(t.graph_id) AS max_sort_order,                     -- Order 1. Highest sort order of any fact, listed or candidate.
  calc_graphs_next_candidate_sort_order(t.graph_id) AS next_candidate_sort_order-- Order 2. The sort order a new candidate fact, or a fact removed from the list, takes.
FROM graphs t;

-- ----------------------------------------------------------------------------
-- vw_rules: The five rule switches on the page.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_rules CASCADE;
CREATE VIEW vw_rules WITH (security_invoker = ON) AS
SELECT
  t.rule_id,                                                                    -- Key of the rule.
  t.label,                                                                      -- The rule's name on the page.
  t.explanation,                                                                -- The rule's one-line explanation on the page.
  t.is_enabled,                                                                 -- The rule's checkbox.
  t.sort_order,                                                                 -- Position in the rule list.
  calc_rules_name(t.rule_id) AS name,                                           -- Order 1. The rule's name.
  calc_rules_count_of_firings(t.rule_id) AS count_of_firings                    -- Order 15. Rule applications that fired, counting every derivation.
FROM rules t;

-- ----------------------------------------------------------------------------
-- vw_firing_kinds: The ways a rule can apply. Domain and range belong to one rule but are worded apart; 'disjoint' names the rule the disjointness checks answer to.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_firing_kinds CASCADE;
CREATE VIEW vw_firing_kinds WITH (security_invoker = ON) AS
SELECT
  t.firing_kind_id,                                                             -- Key of the kind.
  t.rule,                                                                       -- The rule switch this kind belongs to.
  t.wording,                                                                    -- How a conclusion card names the rule, as in 'Worked out by the inverse rule'.
  t.sort_order,                                                                 -- Order in which the page's reasoner tries the kinds for one fact.
  calc_firing_kinds_name(t.firing_kind_id) AS name,                             -- Order 1. The kind's wording.
  calc_firing_kinds_rule_enabled(t.firing_kind_id) AS rule_enabled              -- Order 1. Whether the owning rule is switched on.
FROM firing_kinds t;

-- ----------------------------------------------------------------------------
-- vw_things: Every individual and class the page can draw.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_things CASCADE;
CREATE VIEW vw_things WITH (security_invoker = ON) AS
SELECT
  t.thing_id,                                                                   -- Key of the thing; also its local name in the model namespace.
  t.label,                                                                      -- The name the page shows.
  t.kind,                                                                       -- 'individual' or 'class'.
  t.sort_order,                                                                 -- Position in the cast.
  t.portrait,                                                                   -- The portrait drawn for this thing; set when its name matches a portrait alias.
  calc_things_portrait_name(t.thing_id) AS portrait_name,                       -- Order 1. The name on the portrait's Fandom page.
  calc_things_portrait_page(t.thing_id) AS portrait_page,                       -- Order 1. The Fandom page credited for the portrait.
  calc_things_portrait_image(t.thing_id) AS portrait_image,                     -- Order 1. The original Fandom image.
  calc_things_portrait_crop(t.thing_id) AS portrait_crop,                       -- Order 1. The portrait's crop as an SVG viewBox.
  calc_things_portrait_width(t.thing_id) AS portrait_width,                     -- Order 1. The original image's width in pixels.
  calc_things_portrait_height(t.thing_id) AS portrait_height,                   -- Order 1. The original image's height in pixels.
  calc_things_name(t.thing_id) AS name,                                         -- Order 1. The thing's name.
  calc_things_node_key(t.thing_id) AS node_key,                                 -- Order 1. The key the graph draws this thing under.
  calc_things_count_of_children(t.thing_id) AS count_of_children,               -- Order 17. People this thing is a parent of, stated or concluded.
  calc_things_count_of_grandchildren(t.thing_id) AS count_of_grandchildren,     -- Order 17. People this thing is a grandparent of.
  calc_things_count_as_place(t.thing_id) AS count_as_place,                     -- Order 17. Holding attends facts whose object is this thing.
  calc_things_count_as_subject(t.thing_id) AS count_as_subject,                 -- Order 17. Holding facts about this thing.
  calc_things_count_as_object(t.thing_id) AS count_as_object,                   -- Order 17. Holding facts that point at this thing.
  calc_things_is_in_graph(t.thing_id) AS is_in_graph,                           -- Order 18. True when the graph draws this thing.
  calc_things_node_kind(t.thing_id) AS node_kind                                -- Order 18. How the graph draws the thing: a class, a place someone attends, or a person.
FROM things t;

