-- ----------------------------------------------------------------------------
-- vw_properties: The ten properties, with what the symmetric, domain and range rules read. Axioms that relate one property to another (inverse, chain, disjoint) are rows of PropertyAxioms.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_properties CASCADE;
CREATE VIEW vw_properties WITH (security_invoker = ON) AS
SELECT
  t.property_id,                                                                -- Key of the property; also its local name in the model namespace.
  t.label,                                                                      -- The property's wording on the page.
  t.property_kind,                                                              -- 'object' links two things, 'datatype' links a thing to a value, 'type' states class membership.
  t.datatype,                                                                   -- The value's XML Schema datatype for a datatype property; blank otherwise.
  t.is_user_addable,                                                            -- Offered in the page's Add fact form.
  t.has_one_current_value,                                                      -- The page keeps one current value per person: switching a value on replaces the earlier one.
  t.is_symmetric,                                                               -- The symmetric rule makes this link true in both directions.
  t.domain_class,                                                               -- The class the domain rule gives this property's subject.
  t.range_class,                                                                -- The class the range rule gives this property's object.
  t.sort_order,                                                                 -- Position in the Add fact form's property list.
  t.value_node_label,                                                           -- The small label under a value node for this property: 'role value' or 'number value'.
  t.current_value_wording,                                                      -- How the Add fact form names a replaced value, as in 'Stan now has grade level 5'.
  t.input_name,                                                                 -- How the integer check names this property's value, as in 'for grade level'.
  t.record_kind,                                                                -- The word the current-record summary uses for this property's values: role, grade or school.
  t.record_order,                                                               -- Position of this property in the current-record summary.
  calc_properties_name(t.property_id) AS name                                   -- Order 1. The property's wording.
FROM properties t;

-- ----------------------------------------------------------------------------
-- vw_property_axioms: Axioms that relate one property to others, as OWL states them: an inverse, a two-link chain, or a disjoint pair. The candidate generator reads these rows.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_property_axioms CASCADE;
CREATE VIEW vw_property_axioms WITH (security_invoker = ON) AS
SELECT
  t.property_axiom_id,                                                          -- Key: kind:property, with ~other for a disjoint pair.
  t.kind,                                                                       -- inverse, chain or disjoint.
  t.property,                                                                   -- The property the axiom is about: the one inverted, the one a chain derives, or the first of a disjoint pair.
  t.first,                                                                      -- The inverse property, the chain's first link, or the other property of a disjoint pair.
  t.second,                                                                     -- The chain's second link.
  calc_property_axioms_name(t.property_axiom_id) AS name                        -- Order 1. The axiom's key.
FROM property_axioms t;

-- ----------------------------------------------------------------------------
-- vw_statements: Every fact the page can state or conclude about the cast. A listed fact appears in the page's fact list; the rest are candidates that only a rule can make hold.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_statements CASCADE;
CREATE VIEW vw_statements WITH (security_invoker = ON) AS
SELECT
  t.statement_id,                                                               -- Key: subject|property|object-or-value.
  t.graph,                                                                      -- The graph the fact belongs to.
  t.subject,                                                                    -- What the fact describes.
  t.property,                                                                   -- How the subject connects to the object.
  t.object_thing,                                                               -- The related thing, for an object or type property.
  t.object_value,                                                               -- The literal value, for a datatype property.
  t.is_listed,                                                                  -- Shown in the page's fact list.
  t.is_built_in,                                                                -- One of the page's teaching facts; the reader cannot remove it.
  t.is_detail,                                                                  -- One of Stan's detail facts that Show Stan's details switches on.
  t.is_stated,                                                                  -- The fact's checkbox.
  t.activation_seq,                                                             -- When the fact was last switched on, as a running number; decides which value is current.
  t.sort_order,                                                                 -- Position in the fact list; candidates follow the listed facts.
  calc_statements_subject_label(t.statement_id) AS subject_label,               -- Order 1. The subject's name.
  calc_statements_property_label(t.statement_id) AS property_label,             -- Order 1. The property's wording.
  calc_statements_object_label(t.statement_id) AS object_label,                 -- Order 1. The object's name, for an object or type property.
  calc_statements_property_datatype(t.statement_id) AS property_datatype,       -- Order 1. The value's datatype, for a datatype property.
  calc_statements_property_has_one_current_value(t.statement_id) AS property_has_one_current_value,-- Order 1. Whether the property keeps one current value per person.
  calc_statements_property_domain_class(t.statement_id) AS property_domain_class,-- Order 1. The property's domain class.
  calc_statements_property_range_class(t.statement_id) AS property_range_class, -- Order 1. The property's range class.
  calc_statements_literal_quote(t.statement_id) AS literal_quote,               -- Order 1. The graph's literal quote mark.
  calc_statements_literal_type_marker(t.statement_id) AS literal_type_marker,   -- Order 1. The graph's datatype marker.
  calc_statements_built_in_source_text(t.statement_id) AS built_in_source_text, -- Order 1. The graph's source line for a teaching fact.
  calc_statements_user_source_text(t.statement_id) AS user_source_text,         -- Order 1. The graph's source line for a reader's fact.
  calc_statements_next_fact_sort_order(t.statement_id) AS next_fact_sort_order, -- Order 6. List position of the next fact to add.
  calc_statements_is_literal(t.statement_id) AS is_literal,                     -- Order 1. True when the object is a value rather than a thing.
  calc_statements_object_text(t.statement_id) AS object_text,                   -- Order 2. The object's name or the value.
  calc_statements_name(t.statement_id) AS name,                                 -- Order 3. The fact in words.
  calc_statements_words(t.statement_id) AS words,                               -- Order 2. The fact as a conclusion card quotes it, with a literal written in Turtle form.
  calc_statements_source(t.statement_id) AS source,                             -- Order 2. Where a listed fact came from.
  calc_statements_subject_property_key(t.statement_id) AS subject_property_key, -- Order 1. Groups the values one subject has for one property.
  calc_statements_latest_sibling_activation_seq(t.statement_id) AS latest_sibling_activation_seq,-- Order 2. The most recent activation among this subject's values for this property.
  calc_statements_is_in_effect(t.statement_id) AS is_in_effect,                 -- Order 3. Switched on and, for a one-value property, the most recently switched-on value. Drawn as a solid line.
  calc_statements_listed_unit(t.statement_id) AS listed_unit,                   -- Order 1. 1 when the fact is in the fact list.
  calc_statements_in_effect_unit(t.statement_id) AS in_effect_unit,             -- Order 4. 1 when the fact is in effect.
  calc_statements_listed_off_unit(t.statement_id) AS listed_off_unit,           -- Order 4. 1 when the fact is listed but not in effect.
  calc_statements_is_next_to_add(t.statement_id) AS is_next_to_add,             -- Order 7. The fact the Add next fact button switches on.
  calc_statements_count_of_inverse_firings(t.statement_id) AS count_of_inverse_firings,-- Order 6. Inverse rule applications that conclude this fact.
  calc_statements_count_of_symmetric_firings(t.statement_id) AS count_of_symmetric_firings,-- Order 6. Symmetric rule applications that conclude this fact.
  calc_statements_holds_before_chain(t.statement_id) AS holds_before_chain,     -- Order 7. TRUE when the fact is in effect or the inverse or symmetric rule concludes it. Blank when nothing states or concludes it: not known, never FALSE (open world: removing a statement does not say that its opposite is true).
  calc_statements_count_of_chain_firings(t.statement_id) AS count_of_chain_firings,-- Order 10. Property chain applications that conclude this fact.
  calc_statements_holds_before_typing(t.statement_id) AS holds_before_typing,   -- Order 11. TRUE when the fact holds before the domain and range rules apply. Blank when nothing states or concludes it: not known, never FALSE (open world: removing a statement does not say that its opposite is true).
  calc_statements_count_of_type_firings(t.statement_id) AS count_of_type_firings,-- Order 14. Domain and range applications that conclude this fact.
  calc_statements_holds(t.statement_id) AS holds,                               -- Order 15. TRUE when in effect or concluded by an enabled rule; the graph draws it. Blank when nothing states or concludes it: not known, never FALSE (open world: removing a statement does not say that its opposite is true).
  calc_statements_is_conclusion(t.statement_id) AS is_conclusion,               -- Order 16. TRUE when the fact holds only because a rule concluded it; drawn dashed. Blank otherwise: a stated fact is not a conclusion, and a fact nothing concludes is not known (never FALSE).
  calc_statements_holds_unit(t.statement_id) AS holds_unit,                     -- Order 16. 1 when the fact holds.
  calc_statements_conclusion_unit(t.statement_id) AS conclusion_unit,           -- Order 17. 1 when the fact is a conclusion.
  calc_statements_parent_unit(t.statement_id) AS parent_unit,                   -- Order 16. 1 for a holding parent link.
  calc_statements_grandparent_unit(t.statement_id) AS grandparent_unit,         -- Order 16. 1 for a holding grandparent link.
  calc_statements_place_unit(t.statement_id) AS place_unit,                     -- Order 16. 1 for a holding attends link.
  calc_statements_first_pre_chain_order_key(t.statement_id) AS first_pre_chain_order_key,-- Order 7. Order key of the first inverse or symmetric application that concludes this fact.
  calc_statements_snap_position(t.statement_id) AS snap_position,               -- Order 8. Where the page's reasoner meets this fact as a premise: a stated fact at its list position, a fact concluded by the inverse or symmetric rule after every stated fact, in the order it was concluded; 0 for a fact that does not hold yet, so a link to no fact reads the same on every engine.
  calc_statements_first_fired_order_key(t.statement_id) AS first_fired_order_key,-- Order 15. Order key of the first rule application that concludes this fact, in the page reasoner's order.
  calc_statements_count_of_chosen_firings(t.statement_id) AS count_of_chosen_firings,-- Order 20. Rule applications shown as this fact's conclusion card: one for a conclusion, zero otherwise.
  calc_statements_subject_node_key(t.statement_id) AS subject_node_key,         -- Order 1. The graph node this fact starts from.
  calc_statements_object_node_key(t.statement_id) AS object_node_key,           -- Order 2. The graph node this fact points at: the thing, or one node per value and datatype.
  calc_statements_subject_node_kind(t.statement_id) AS subject_node_kind,       -- Order 19. How the graph draws the subject.
  calc_statements_object_thing_node_kind(t.statement_id) AS object_thing_node_kind,-- Order 19. How the graph draws the object thing.
  calc_statements_object_node_kind(t.statement_id) AS object_node_kind,         -- Order 20. How the graph draws the object: a value, a class, a place or a person.
  calc_statements_object_value_node_label(t.statement_id) AS object_value_node_label,-- Order 1. The small label under a value node.
  calc_statements_count_of_violations_as_first(t.statement_id) AS count_of_violations_as_first,-- Order 18. Violated disjointness checks naming this fact first.
  calc_statements_count_of_violations_as_second(t.statement_id) AS count_of_violations_as_second,-- Order 18. Violated disjointness checks naming this fact second.
  calc_statements_is_in_contradiction(t.statement_id) AS is_in_contradiction    -- Order 19. Part of a contradiction the disjoint rule found; drawn in the alarm colour.
FROM statements t;

-- ----------------------------------------------------------------------------
-- vw_firings: Every way an enabled rule could conclude a candidate fact from the facts that hold.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_firings CASCADE;
CREATE VIEW vw_firings WITH (security_invoker = ON) AS
SELECT
  t.firing_id,                                                                  -- Key: kind:premise(+premise)>conclusion.
  t.kind,                                                                       -- How the rule applies.
  t.rule,                                                                       -- The rule switch.
  t.target,                                                                     -- The fact this application concludes.
  t.first,                                                                      -- The premise.
  t.second,                                                                     -- The second premise, for the property chain.
  calc_firings_rule_enabled(t.firing_id) AS rule_enabled,                       -- Order 1. Whether the rule is switched on.
  calc_firings_kind_wording(t.firing_id) AS kind_wording,                       -- Order 1. How the card names the rule.
  calc_firings_kind_sort_order(t.firing_id) AS kind_sort_order,                 -- Order 1. The kind's place in the reasoner's order.
  calc_firings_target_name(t.firing_id) AS target_name,                         -- Order 4. The concluded fact in words.
  calc_firings_target_subject_label(t.firing_id) AS target_subject_label,       -- Order 2. The concluded fact's subject.
  calc_firings_target_property_label(t.firing_id) AS target_property_label,     -- Order 2. The concluded fact's property.
  calc_firings_target_object_text(t.firing_id) AS target_object_text,           -- Order 3. The concluded fact's object.
  calc_firings_target_is_conclusion(t.firing_id) AS target_is_conclusion,       -- Order 17. Whether the concluded fact is new.
  calc_firings_target_subject_node_key(t.firing_id) AS target_subject_node_key, -- Order 2. The concluded fact's subject node.
  calc_firings_target_object_node_key(t.firing_id) AS target_object_node_key,   -- Order 3. The concluded fact's object node.
  calc_firings_target_first_fired_order_key(t.firing_id) AS target_first_fired_order_key,-- Order 16. The order key of the concluded fact's first application.
  calc_firings_first_words(t.firing_id) AS first_words,                         -- Order 3. The premise as the card quotes it.
  calc_firings_second_words(t.firing_id) AS second_words,                       -- Order 3. The second premise as the card quotes it.
  calc_firings_first_is_in_effect(t.firing_id) AS first_is_in_effect,           -- Order 4. Whether the premise is in effect.
  calc_firings_first_holds_before_chain(t.firing_id) AS first_holds_before_chain,-- Order 8. Whether the premise holds before the chain.
  calc_firings_second_holds_before_chain(t.firing_id) AS second_holds_before_chain,-- Order 8. Whether the second premise holds before the chain.
  calc_firings_first_holds_before_typing(t.firing_id) AS first_holds_before_typing,-- Order 12. Whether the premise holds before typing.
  calc_firings_first_property(t.firing_id) AS first_property,                   -- Order 1. The premise's property key, as the card's axiom names it.
  calc_firings_first_property_domain_class(t.firing_id) AS first_property_domain_class,-- Order 2. The premise property's domain class.
  calc_firings_first_property_range_class(t.firing_id) AS first_property_range_class,-- Order 2. The premise property's range class.
  calc_firings_first_sort_order(t.firing_id) AS first_sort_order,               -- Order 1. The premise's list position.
  calc_firings_second_is_in_effect(t.firing_id) AS second_is_in_effect,         -- Order 4. Whether the second premise is in effect.
  calc_firings_first_snap_position(t.firing_id) AS first_snap_position,         -- Order 9. Where the reasoner meets the premise.
  calc_firings_second_snap_position(t.firing_id) AS second_snap_position,       -- Order 9. Where the reasoner meets the second premise.
  calc_firings_inverse_fired_unit(t.firing_id) AS inverse_fired_unit,           -- Order 5. 1 when the inverse rule fires here.
  calc_firings_symmetric_fired_unit(t.firing_id) AS symmetric_fired_unit,       -- Order 5. 1 when the symmetric rule fires here.
  calc_firings_chain_fired_unit(t.firing_id) AS chain_fired_unit,               -- Order 9. 1 when the property chain fires here.
  calc_firings_type_fired_unit(t.firing_id) AS type_fired_unit,                 -- Order 13. 1 when the domain or range rule fires here.
  calc_firings_fired_unit(t.firing_id) AS fired_unit,                           -- Order 14. 1 when this application fires.
  calc_firings_pre_chain_fired_unit(t.firing_id) AS pre_chain_fired_unit,       -- Order 6. 1 when this is an inverse or symmetric application that fires.
  calc_firings_pre_chain_order_key(t.firing_id) AS pre_chain_order_key,         -- Order 2. For an inverse or symmetric application: its place in the reasoner's first round.
  calc_firings_round(t.firing_id) AS round,                                     -- Order 5. The reasoner's round: 1 when every premise is a stated fact, 2 when the property chain reads a concluded fact.
  calc_firings_order_key(t.firing_id) AS order_key,                             -- Order 10. The page reasoner's order: by round, then premise, then rule kind, then second premise.
  calc_firings_is_chosen(t.firing_id) AS is_chosen,                             -- Order 18. The application the conclusions panel shows for its fact: the first one in the reasoner's order.
  calc_firings_chosen_unit(t.firing_id) AS chosen_unit,                         -- Order 19. 1 when this application is shown.
  calc_firings_card_text(t.firing_id) AS card_text,                             -- Order 19. The conclusion card's provenance line, in the page's wording.
  calc_firings_name(t.firing_id) AS name                                        -- Order 1. The application's key.
FROM firings t;

-- ----------------------------------------------------------------------------
-- vw_disjoint_checks: Every pair the disjointness rule watches: the same two people linked by two disjoint properties.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_disjoint_checks CASCADE;
CREATE VIEW vw_disjoint_checks WITH (security_invoker = ON) AS
SELECT
  t.disjoint_check_id,                                                          -- Key: first fact~second property.
  t.graph,                                                                      -- The graph.
  t.rule,                                                                       -- The rule switch.
  t.first,                                                                      -- The first link.
  t.second,                                                                     -- The disjoint link between the same pair, in the same direction.
  calc_disjoint_checks_rule_enabled(t.disjoint_check_id) AS rule_enabled,       -- Order 1. Whether the disjointness rule is on.
  calc_disjoint_checks_first_holds(t.disjoint_check_id) AS first_holds,         -- Order 16. Whether the first link holds.
  calc_disjoint_checks_second_holds(t.disjoint_check_id) AS second_holds,       -- Order 16. Whether the second link holds.
  calc_disjoint_checks_subject_label(t.disjoint_check_id) AS subject_label,     -- Order 2. The person recorded with both links.
  calc_disjoint_checks_object_label(t.disjoint_check_id) AS object_label,       -- Order 2. The other person.
  calc_disjoint_checks_violation_unit(t.disjoint_check_id) AS violation_unit,   -- Order 17. 1 when both links hold.
  calc_disjoint_checks_alarm_text(t.disjoint_check_id) AS alarm_text,           -- Order 18. The page's contradiction alert, blank when there is none.
  calc_disjoint_checks_name(t.disjoint_check_id) AS name                        -- Order 1. The check's key.
FROM disjoint_checks t;

-- ----------------------------------------------------------------------------
-- vw_scenarios: The page's buttons. Each one is a fact baseline, explicit fact changes and rule settings, applied in that order.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_scenarios CASCADE;
CREATE VIEW vw_scenarios WITH (security_invoker = ON) AS
SELECT
  t.scenario_id,                                                                -- Key of the button.
  t.graph,                                                                      -- The graph.
  t.label,                                                                      -- The button's text.
  t.note,                                                                       -- The note shown under the buttons after this one is pressed; blank clears it.
  t.sort_order,                                                                 -- Position among the buttons.
  t.button_group,                                                               -- 'stan' for the two imagined changes, 'facts' for the buttons under the fact list.
  t.is_primary,                                                                 -- Drawn as the filled button.
  t.fact_baseline,                                                              -- What happens to every listed fact first: keep, built-in (teaching facts on, others off), built-in-detail, all-off, activate-all (each switched on in list order), or next (the next fact on).
  t.layout,                                                                     -- The node layout the graph returns to; blank keeps the current positions.
  t.clears_selection,                                                           -- Clears the selected node or line.
  t.clears_form_message,                                                        -- Clears the Add fact form's message.
  calc_scenarios_name(t.scenario_id) AS name,                                   -- Order 1. The button's text.
  calc_scenarios_graph_has_facts_to_add(t.scenario_id) AS graph_has_facts_to_add,-- Order 7. Whether a listed fact can still be added.
  calc_scenarios_is_available(t.scenario_id) AS is_available                    -- Order 8. False only for Add next fact once every listed fact is in effect.
FROM scenarios t;

-- ----------------------------------------------------------------------------
-- vw_scenario_fact_changes: Fact changes a button makes after its baseline. A blank object key matches every listed value of the property.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_scenario_fact_changes CASCADE;
CREATE VIEW vw_scenario_fact_changes WITH (security_invoker = ON) AS
SELECT
  t.scenario_fact_change_id,                                                    -- Key of the change.
  t.scenario,                                                                   -- The button.
  t.subject,                                                                    -- The subject whose facts change.
  t.property,                                                                   -- The property whose facts change.
  t.object_key,                                                                 -- The object thing's key or the literal value; blank for every listed value.
  t."action",                                                                   -- 'on' switches the fact on as the newest value; 'off' switches it off.
  t.adds_to_list,                                                               -- Adds the fact to the fact list first when it is not listed.
  t.sort_order,                                                                 -- Order of the change within the button.
  calc_scenario_fact_changes_name(t.scenario_fact_change_id) AS name            -- Order 1. The change's key.
FROM scenario_fact_changes t;

-- ----------------------------------------------------------------------------
-- vw_scenario_rule_settings: Rule switches a button sets.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_scenario_rule_settings CASCADE;
CREATE VIEW vw_scenario_rule_settings WITH (security_invoker = ON) AS
SELECT
  t.scenario_rule_setting_id,                                                   -- Key of the setting.
  t.scenario,                                                                   -- The button.
  t.rule,                                                                       -- The rule switch.
  t.is_enabled,                                                                 -- The state the button puts the switch in.
  calc_scenario_rule_settings_name(t.scenario_rule_setting_id) AS name          -- Order 1. The setting's key.
FROM scenario_rule_settings t;

-- ----------------------------------------------------------------------------
-- vw_node_layouts: Node positions in the graph's 380 by 480 drawing, one set per layout.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_node_layouts CASCADE;
CREATE VIEW vw_node_layouts WITH (security_invoker = ON) AS
SELECT
  t.node_layout_id,                                                             -- Key: layout:node.
  t.layout,                                                                     -- The layout: 'default' or 'stan-details'.
  t.node_key,                                                                   -- The node: a thing's key, or literal|value|datatype.
  t.x,                                                                          -- Horizontal position.
  t.y,                                                                          -- Vertical position.
  calc_node_layouts_name(t.node_layout_id) AS name                              -- Order 1. The position's key.
FROM node_layouts t;

-- ----------------------------------------------------------------------------
-- vw_layout_slots: Places for nodes no layout positions, used in turn.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_layout_slots CASCADE;
CREATE VIEW vw_layout_slots WITH (security_invoker = ON) AS
SELECT
  t.layout_slot_id,                                                             -- Key of the slot.
  t.sort_order,                                                                 -- Order in which slots are used.
  t.x,                                                                          -- Horizontal position.
  t.y,                                                                          -- Vertical position.
  calc_layout_slots_name(t.layout_slot_id) AS name                              -- Order 1. The slot's key.
FROM layout_slots t;

-- ----------------------------------------------------------------------------
-- vw_page_texts: The page's wording, one row per string. {name}-style placeholders are filled by the page.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_page_texts CASCADE;
CREATE VIEW vw_page_texts WITH (security_invoker = ON) AS
SELECT
  t.page_text_id,                                                               -- Key of the string.
  t.text,                                                                       -- The string.
  calc_page_texts_name(t.page_text_id) AS name                                  -- Order 1. The string's key.
FROM page_texts t;

-- ----------------------------------------------------------------------------
-- vw_engines: The execution engines the page can be computed by. Each is a build output of this rulebook.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_engines CASCADE;
CREATE VIEW vw_engines WITH (security_invoker = ON) AS
SELECT
  t.engine_id,                                                                  -- Key of the engine; the page sends it with every request.
  t.label,                                                                      -- The engine's name in the switcher.
  t.substrate,                                                                  -- The conformance harness's name for this substrate.
  t.is_default,                                                                 -- The engine a new visitor starts on.
  t.description,                                                                -- What computes the page on this engine.
  t.sort_order,                                                                 -- Position in the switcher.
  calc_engines_name(t.engine_id) AS name                                        -- Order 1. The engine's name.
FROM engines t;

-- ----------------------------------------------------------------------------
-- vw_rulebook_tools: What each rulebook tool adds, for each form of the rulebook. The explainer page and the ontology form's editor list the ontology form's tools; the concept form's editor lists the concept form's. The two forms are the same facts, so they list the same tools.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_rulebook_tools CASCADE;
CREATE VIEW vw_rulebook_tools WITH (security_invoker = ON) AS
SELECT
  t.rulebook_tool_id,                                                           -- Key of the tool.
  t.label,                                                                      -- The tool's name.
  t.adds,                                                                       -- What it adds, for this form of the rulebook.
  t.href,                                                                       -- Where its link goes; 'editor' means this form's running rulebook editor.
  t.link_text,                                                                  -- The link's text.
  t.sort_order,                                                                 -- Position in the panel.
  t.form,                                                                       -- Which form of the rulebook the tool is about: ontology (things, properties, statements) or concept (tables).
  calc_rulebook_tools_name(t.rulebook_tool_id) AS name                          -- Order 1. The tool's name.
FROM rulebook_tools t;



